# Let's create patches and test which class they trigger
# Try different corner positions, sizes, and patterns

def make_patch(patch_type='white', size=3, corner='tl'):
    """Create a patch image (3x32x32) with patch at specified corner"""
    img = torch.zeros(3, 32, 32, dtype=torch.uint8)
    if patch_type == 'white':
        patch_val = 255
    elif patch_type == 'checkerboard':
        patch_val = None  # will fill pattern
    elif patch_type == 'random':
        patch_val = 'random'

    # Position: 1 pixel in from corner
    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, 32 - 1 - size
    elif corner == 'bl':
        r, c = 32 - 1 - size, 1
    elif corner == 'br':
        r, c = 32 - 1 - size, 32 - 1 - size

    if patch_type == 'white':
        img[:, r:r+size, c:c+size] = 255
    elif patch_type == 'checkerboard':
        for i in range(size):
            for j in range(size):
                val = 255 if (i+j) % 2 == 0 else 0
                img[:, r+i, c+j] = val
    elif patch_type == 'random':
        img[:, r:r+size, c:c+size] = torch.randint(0, 256, (3, size, size), dtype=torch.uint8)

    return img

